ValidationRule.errorConditionFormula:
AND( OR(ISPICKVAL( StageName , '1 - Qualification'),ISPICKVAL( StageName , '2 - Solution Developed'),ISPICKVAL( StageName , '3 - Solution Agreed'),ISPICKVAL( StageName , '4 - Negotiate')),
ISPICKVAL( ForecastCategoryName , 'Closed'), NOT($Permission.VR_Bypass_Permission)
)
